async function scanBundle(input, deliver) {
  let count = 0;
  let line = 0;
  let fragments = [];

  async function processLine(text) {
    line++;
    if (text.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    count++;
    return (await deliver(value, line)) !== false;
  }

  try {
    const decoder = new TextDecoder("utf-8");

    while (true) {
      const chunk = await input.read();
      const eof = chunk === null;
      const text = eof
        ? decoder.decode()
        : decoder.decode(chunk, { stream: true });

      let start = 0;
      let end;
      while ((end = text.indexOf("\n", start)) !== -1) {
        fragments.push(text.slice(start, end));
        const row = fragments.join("");
        fragments = [];
        start = end + 1;

        if (!(await processLine(row))) return count;
      }

      if (start < text.length) {
        fragments.push(text.slice(start));
      }

      if (eof) {
        if (fragments.length > 0) {
          const row = fragments.join("");
          fragments = [];
          await processLine(row);
        }
        return count;
      }
    }
  } finally {
    await input.close();
  }
}
